def rounded_avg(n, m):
    from math import floor

    if n > m:
        return -1

    total = (m + n) * (m - n + 1) // 2  # Formula to sum an arithmetic series
    avg = floor(total / (m - n + 1))  # Average rounded to the nearest integer
    return bin(avg)
